const classes=['Striker','Warden','Skirmisher','Ranger','Mystic','Sentinel','Arcanist','Support','Titan'];
const moveNames=['Ember volley','Vine lash','Tidal pulse','Arc flash','Dusk bolt','Stone barrage','Frost lance','Petal storm','Solar ray'];
const ultimateNames=['Inferno bloom','Ancient roots','Maelstrom','Thunder crown','Eclipse fall','Meteor break','Polar nova','Spring eruption','Supernova'];
const classStats=[[105,71,48,82,51,74],[125,61,79,74,72,56],[96,66,52,79,62,92],[90,70,47,86,54,99],[99,55,54,97,71,79],[140,88,94,44,64,38],[108,52,61,93,83,65],[110,59,65,80,88,76],[155,95,85,110,92,72]];
const coreMon=mon,coreWorld=world,coreTick=tick,coreStart=start,coreFinish=finish,coreShoot=shoot,coreUI=updateUI,coreTab=tab;
let connectedAddress=null,walletProvider=null,walletTimer=null,balanceController=null,walletEpoch=0;
let duel={energy:100,rivalEnergy:100,cooldowns:[0,0,0,0],shield:0,rivalShield:0,auto:false,ai:2,round:0,damage:0,rivalDamage:0,log:[],teamHP:{},switchCD:0};
let motion={id:null,origin:null,point:null,target:null,vector:null};let skinCache={};
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function identity(id){const scope=connectedAddress||'guest';const key=scope+':'+id;if(skinCache[key])return skinCache[key];save.dna??={};save.dna[scope]??={};if(!save.dna[scope][id]){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);save.dna[scope][id]=[...bytes].map(v=>v.toString(16).padStart(2,'0')).join('');try{localStorage.setItem('pocketmonstars-v1',JSON.stringify(save))}catch(e){}}
const dna=save.dna[scope][id],n=hash(dna);return skinCache[key]={dna,n,scope,pattern:['Starlit','Striped','Freckled','Crescent'][n%4],aura:['Jade','Amber','Rose','Azure','Violet','Opal'][(n>>>4)%6],nature:['Bold','Serene','Swift','Curious','Steady','Spirited'][(n>>>8)%6],hue:(n%81)-40}}
function stats(id){const i=identity(id),b=classStats[id],l=level(id)-1;return b.map((v,k)=>v+(k===0?l*15:l*3)+((i.n>>>(k*4))&7))}
mon=function(c,id,x,y,scale=3,t=0,flip=false){const i=identity(id);c.save();c.filter=`hue-rotate(${i.hue}deg)`;coreMon(c,id,x,y,scale,t,flip);c.filter='none';c.fillStyle=['#fff3b1','#d5ffd7','#c4efff','#ffcbef'][i.n%4];let mark=scale*1.15;for(let k=0;k<2+i.n%3;k++)c.fillRect(x+(k-1)*scale*3,y+Math.sin(t)*1.5-scale*(8+(k%2)),mark,mark);c.restore()};
function effectiveness(at,def){const strong={EMBER:['GROVE','FROST'],TIDE:['EMBER','STONE'],GROVE:['TIDE','STONE'],SPARK:['TIDE'],STONE:['SPARK','EMBER'],FROST:['GROVE'],SHADE:['ASTRAL'],ASTRAL:['SHADE']};if(strong[at]?.includes(def))return 1.5;if(strong[def]?.includes(at))return .7;return 1}
function moves(id=save.selected){return [{name:moveNames[id],cost:18,cd:1.1,power:1,unlock:1,kind:'special',type:species[id].type},{name:ultimateNames[id],cost:38,cd:5,power:2.1,unlock:3,kind:'special',type:species[id].type},{name:'Quick strike',cost:5,cd:.65,power:.65,unlock:1,kind:'physical',type:'NEUTRAL'},{name:'Aegis guard',cost:22,cd:7,power:0,unlock:2,kind:'guard',type:'GUARD'}]}
function renderMoves(){const list=moves();$('moveGrid').innerHTML='';list.forEach((m,k)=>{const b=document.createElement('button');b.className='move';b.id='skill'+k;b.innerHTML=`<span class="move-key">${k+1}</span><small>${m.type}</small><strong>${m.name}</strong><small class="move-info">${m.cost} energy · ${m.cd}s cooldown</small><i class="cooldown-fill"></i>`;b.onclick=()=>skill(k);$('moveGrid').append(b)})}
function team(){const strip=$('teamStrip');strip.innerHTML='';save.owned.slice(0,6).forEach(id=>{const b=document.createElement('button');b.className='team-member'+(id===save.selected?' selected':'');b.innerHTML=`<canvas width="70" height="55"></canvas><span>${species[id].name}<small>${classes[id]} · LV ${level(id)}</small></span>`;mon(b.querySelector('canvas').getContext('2d'),id,35,31,1.6,0);b.onclick=()=>switchPartner(id);strip.append(b)})}
function switchPartner(id){if(id===save.selected)return;if(active&&mode!=='duel'){toast('Return to camp to change partners in this mode.');return}if(active&&(paused||duel.switchCD>0)){toast(paused?'Resume the duel first.':'Team switch is cooling down.');return}if(active){duel.teamHP[save.selected]=player.hp;if(duel.teamHP[id]===0){toast('That partner has fainted this duel.');return}}save.selected=id;player.max=mode==='duel'?stats(id)[0]:maxhp();player.hp=active?(duel.teamHP[id]??player.max):player.max;duel.switchCD=3;duel.energy=Math.min(duel.energy,75);renderMoves();team();persist();if(active)battleLog(species[id].name+' enters the field.');else toast(species[id].name+' is ready.')}
function battleLog(message){duel.log.unshift(message);duel.log=duel.log.slice(0,5);$('battlePrompt').textContent=message;$('feed').textContent=duel.log.join(' · ')}
function updateArenaUI(){const isDuel=mode==='duel';$('duelHud').classList.toggle('hidden',!isDuel);$('battleControls').classList.toggle('hidden',!isDuel);document.querySelector('.arena').classList.toggle('duel-stage',isDuel);if(!isDuel)return;
$('allyName').textContent=species[save.selected].name+' · Lv '+level();$('allyClass').textContent=classes[save.selected]+' / '+species[save.selected].type;$('allyHP').style.width=Math.max(0,player.hp/player.max*100)+'%';$('allyNumbers').textContent=Math.ceil(Math.max(0,player.hp))+' / '+player.max+' HP · '+Math.floor(duel.energy)+' EN';$('allyEnergy').style.width=duel.energy+'%';const e=enemies[0];$('rivalName').textContent=e?species[e.id].name:'Challenger';$('rivalClass').textContent=e?classes[e.id]+' / '+species[e.id].type:'AI opponent';$('rivalHP').style.width=e?Math.max(0,e.hp/e.max*100)+'%':'100%';$('rivalNumbers').textContent=e?Math.ceil(Math.max(0,e.hp))+' / '+e.max+' HP · '+Math.floor(duel.rivalEnergy)+' EN':'Awaiting battle';$('rivalEnergy').style.width=duel.rivalEnergy+'%';moves().forEach((m,k)=>{const b=$('skill'+k);if(!b)return;const locked=level()<m.unlock,cool=duel.cooldowns[k]>0;b.disabled=!active||paused||locked||cool||duel.energy<m.cost;b.querySelector('.move-info').textContent=locked?'Unlocks at level '+m.unlock:cool?duel.cooldowns[k].toFixed(1)+'s · recharging':m.cost+' energy · '+m.cd+'s cooldown';b.querySelector('.cooldown-fill').style.width=Math.max(0,duel.cooldowns[k]/m.cd*100)+'%'})}
updateUI=function(){coreUI();updateArenaUI()};
world=function(t){if(mode!=='duel'){coreWorld(t);return}ctx.fillStyle='#12271f';ctx.fillRect(0,0,960,550);ctx.fillStyle='#233930';ctx.fillRect(0,0,960,95);for(let row=0;row<4;row++)for(let i=0;i<64;i++){let n=hash('seat'+row+':'+i);ctx.fillStyle=['#c9cda0','#6d9974','#d3a279','#809fc1','#9d86ab'][n%5];ctx.fillRect(i*15+4,15+row*17,7,7);ctx.fillStyle='#15251e';ctx.fillRect(i*15,26+row*17,15,4)}ctx.fillStyle='#1a2c25';ctx.fillRect(0,88,960,32);ctx.fillStyle='#dfff84';ctx.font='bold 12px monospace';ctx.textAlign='center';for(let i=0;i<4;i++)ctx.fillText('✦ POCKETMONSTARS / WILD LEAGUE',120+i*240,109);for(let x=0;x<960;x+=32){ctx.fillStyle=(x/32)%2?'#36513a':'#d3d99c';ctx.fillRect(x,122,25,5)}ctx.fillStyle='#456d43';ctx.fillRect(30,136,900,365);for(let i=0;i<10;i++){ctx.fillStyle=i%2?'#4d7547':'#456d43';ctx.fillRect(30+i*90,136,90,365)}for(const p of terrain){if(p.y<140||p.y>496||p.x<35||p.x>925)continue;ctx.fillStyle=p.k>.7?'#6c8b52':'#3c633b';ctx.fillRect(p.x,p.y,2,3)}ctx.strokeStyle='#dce4ae88';ctx.lineWidth=3;ctx.strokeRect(55,155,850,325);ctx.beginPath();ctx.moveTo(480,155);ctx.lineTo(480,480);ctx.stroke();ctx.beginPath();ctx.ellipse(480,317,85,64,0,0,7);ctx.stroke();ctx.strokeRect(55,239,78,156);ctx.strokeRect(827,239,78,156);ctx.fillStyle='#dfff84';ctx.fillRect(477,314,6,6);ctx.fillStyle='#192f24';ctx.fillRect(0,505,960,45);ctx.font='11px monospace';ctx.fillStyle='#b8cda2';ctx.fillText('DRAG TO MOVE    /    FOUR MOVES. ONE CHAMPION.',480,532);
if(motion.origin&&motion.point){ctx.strokeStyle='#e5ffb16a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(motion.origin.x,motion.origin.y,40,0,7);ctx.stroke();ctx.fillStyle='#dfff8480';ctx.beginPath();ctx.arc(motion.point.x,motion.point.y,13,0,7);ctx.fill()}if(motion.target){ctx.strokeStyle='#dfff84';ctx.beginPath();ctx.arc(motion.target.x,motion.target.y,8+Math.sin(t*6)*2,0,7);ctx.stroke()}if(duel.shield>0){ctx.strokeStyle='#9edbed';ctx.lineWidth=3;ctx.beginPath();ctx.arc(player.x,player.y,38,0,7);ctx.stroke()}};
start=function(){coreStart();motion.target=null;motion.vector=null;duel.cooldowns=[0,0,0,0];duel.energy=100;duel.rivalEnergy=100;duel.shield=0;duel.switchCD=0;duel.ai=2;duel.damage=0;duel.rivalDamage=0;duel.teamHP={};duel.log=[];if(mode==='duel'){player.x=260;player.y=320;player.max=stats(save.selected)[0];player.hp=player.max;enemies=[];bullets=[];let id=Math.random()*8|0;if(id===save.selected)id=(id+1)%8;const hp=classStats[id][0]+(level()-1)*12;enemies.push({id,x:730,y:320,hp,max:hp,boss:false,hit:0,shoot:2,speed:40});$('touchFire').textContent='MOVE 1';$('location').textContent='VERDANT STADIUM';battleLog('Go, '+species[save.selected].name+'! Drag to move. Choose a move.');$('gameStatus').textContent='● FREE DUEL · AI RIVAL'}else $('touchFire').textContent='FIRE';team();renderMoves();updateArenaUI()};$('start').onclick=()=>start();
finish=function(win=false){if(mode!=='duel'){coreFinish(win);return}active=false;keys={};motion={id:null,origin:null,point:null,target:null,vector:null};$('touch').classList.add('hidden');$('splash').classList.remove('hidden');$('splash').querySelector('.huge').innerHTML=win?'That’s your<br><em>champion moment.</em>':'Every legend<br><em>learns to rise.</em>';$('splash').querySelector('p').textContent=win?'Victory! +50 experience and +20 camp shards. No wallet funds moved.':'Your team gave it everything. Heal up and take on a new rival.';$('start').innerHTML='Next duel <span>↗</span>';if(win){save.duelWins=(save.duelWins||0)+1;save.streak=(save.streak||0)+1;save.bestStreak=Math.max(save.bestStreak||0,save.streak);gain(50,20)}else save.streak=0;battleLog((win?'Victory! ':'Defeat. ')+'Damage dealt '+duel.damage+' · received '+duel.rivalDamage+' · Best streak '+(save.bestStreak||0));$('gameStatus').textContent=win?'✦ Victory · '+save.streak+' win streak':'● Duel complete';persist();renderMoves()};
function skill(k){if(mode!=='duel'){if(k===0)coreShoot();return}if(!active||paused)return;const m=moves()[k];if(level()<m.unlock){toast('Unlocks at level '+m.unlock);return}if(duel.cooldowns[k]>0||duel.energy<m.cost)return;const e=enemies[0];if(!e)return;duel.energy-=m.cost;duel.cooldowns[k]=m.cd;if(k===3){duel.shield=2.5;burst(player.x,player.y,'#a4e6ff',18);battleLog(species[save.selected].name+' raises Aegis guard.');tone(780);return}const a=Math.atan2(e.y-player.y,e.x-player.x);bullets.push({x:player.x,y:player.y-6,vx:Math.cos(a)*(k===2?530:340),vy:Math.sin(a)*(k===2?530:340),life:2.5,color:species[save.selected].accent,enemy:false,skill:k,power:m.power,kind:m.kind,type:m.type});battleLog(species[save.selected].name+' used '+m.name+'!');tone(k===1?520:350)}
shoot=function(aim){if(mode==='duel')skill(0);else coreShoot(aim)};
function damageTo(e,b){const a=stats(save.selected),d=classStats[e.id],special=b.kind==='special';const eff=effectiveness(b.type,species[e.id].type);return {amount:Math.max(4,Math.round((special?a[3]:a[1])*(b.power||1)*.32*eff*(100/(75+(special?d[4]:d[2]))))),eff}}
tick=function(dt){if(mode!=='duel'){applyMotion(dt,false);coreTick(dt);return}elapsed+=dt;player.inv-=dt;player.dash-=dt;player.shot-=dt;duel.shield-=dt;duel.switchCD-=dt;duel.energy=Math.min(100,duel.energy+10*dt);duel.rivalEnergy=Math.min(100,duel.rivalEnergy+9*dt);duel.cooldowns=duel.cooldowns.map(t=>Math.max(0,t-dt));let dx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),dy=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);if(dx||dy){motion.target=null;const len=Math.hypot(dx,dy);player.x+=dx/len*(95+stats(save.selected)[5]*1.2)*dt;player.y+=dy/len*(95+stats(save.selected)[5]*1.2)*dt}applyMotion(dt,true);player.x=Math.max(75,Math.min(885,player.x));player.y=Math.max(177,Math.min(456,player.y));if(keys[' ']||duel.auto)skill(0);
const e=enemies[0];if(!e)return;e.hit-=dt;let a=Math.atan2(player.y-e.y,player.x-e.x),dist=Math.hypot(e.x-player.x,e.y-player.y);if(dist>240){e.x+=Math.cos(a)*e.speed*dt;e.y+=Math.sin(a)*e.speed*dt}else if(dist<110){e.x-=Math.cos(a)*e.speed*dt;e.y-=Math.sin(a)*e.speed*dt}e.y+=Math.sin(elapsed*1.8)*24*dt;e.x=Math.max(80,Math.min(880,e.x));e.y=Math.max(185,Math.min(450,e.y));duel.ai-=dt;if(duel.ai<=0&&duel.rivalEnergy>=18){duel.ai=1.5+Math.random();duel.rivalEnergy-=18;const aim=Math.atan2(player.y-e.y,player.x-e.x);bullets.push({x:e.x,y:e.y-6,vx:Math.cos(aim)*220,vy:Math.sin(aim)*220,life:4,color:species[e.id].accent,enemy:true,type:species[e.id].type})}
for(const b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.enemy&&Math.hypot(b.x-player.x,b.y-player.y)<25){b.life=0;if(duel.shield>0){burst(b.x,b.y,'#aceaff');texts.push({x:player.x,y:player.y-40,text:'BLOCK',life:.8})}else if(player.inv<=0){const ps=stats(save.selected),d=Math.max(5,Math.round(classStats[e.id][3]*.19*effectiveness(b.type,species[save.selected].type)*100/(80+ps[4])));player.hp=Math.max(0,player.hp-d);duel.rivalDamage+=d;duel.teamHP[save.selected]=player.hp;player.inv=.15;texts.push({x:player.x,y:player.y-35,text:'−'+d,life:.8});burst(player.x,player.y,'#e6a893');tone(130)}}else if(!b.enemy&&Math.hypot(b.x-e.x,b.y-e.y)<28){b.life=0;const d=damageTo(e,b);e.hp-=d.amount;duel.damage+=d.amount;duel.hits=(duel.hits||0)+1;burst(e.x,e.y,b.color,15);texts.push({x:e.x,y:e.y-35,text:d.amount+(d.eff>1?'!':''),life:.9});if(d.eff>1)battleLog('Super effective! '+d.amount+' damage.');if(e.hp<=0){e.hp=0;save.wins++;finish(true);break}}}bullets=bullets.filter(b=>b.life>0&&b.x>40&&b.x<920&&b.y>135&&b.y<500);if(player.hp<=0){const next=save.owned.slice(0,6).find(id=>id!==save.selected&&duel.teamHP[id]!==0);if(next!==undefined){duel.switchCD=0;switchPartner(next);player.inv=1;battleLog('A partner fainted. '+species[next].name+' takes the field.')}else finish(false)}$('time').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0');updateUI()};
function applyMotion(dt,isDuel){if(!active||paused)return;let dx=0,dy=0;if(motion.vector){dx=motion.vector.x;dy=motion.vector.y}else if(motion.target){let x=motion.target.x-player.x,y=motion.target.y-player.y,l=Math.hypot(x,y);if(l<8){motion.target=null;return}dx=x/l;dy=y/l}const speed=isDuel?95+stats(save.selected)[5]*1.2:species[save.selected].speed;player.x+=dx*speed*dt;player.y+=dy*speed*dt;if(!isDuel){player.x=Math.max(55,Math.min(905,player.x));player.y=Math.max(75,Math.min(475,player.y))}}
function point(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*960/r.width,y:(e.clientY-r.top)*550/r.height}}
canvas.addEventListener('pointerdown',e=>{if(!active||paused)return;e.preventDefault();canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);motion.id=e.pointerId;motion.origin=point(e);motion.point=point(e);motion.vector=null;motion.target=null});canvas.addEventListener('pointermove',e=>{if(e.pointerId!==motion.id||!motion.origin)return;e.preventDefault();let p=point(e),x=p.x-motion.origin.x,y=p.y-motion.origin.y,len=Math.hypot(x,y);motion.point={x:motion.origin.x+x/Math.max(1,len)*Math.min(40,len),y:motion.origin.y+y/Math.max(1,len)*Math.min(40,len)};motion.vector=len>5?{x:x/len*Math.min(1,len/40),y:y/len*Math.min(1,len/40)}:null});function release(e){if(e.pointerId!==motion.id)return;if(!motion.vector)motion.target=point(e);motion.id=null;motion.origin=null;motion.point=null;motion.vector=null}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',()=>{motion={id:null,origin:null,point:null,target:null,vector:null}});
window.addEventListener('keydown',e=>{if(active&&mode==='duel'&&/^[1-4]$/.test(e.key)&&!e.repeat){e.preventDefault();skill(Number(e.key)-1)}});window.addEventListener('blur',()=>{motion={id:null,origin:null,point:null,target:null,vector:null}});
$('autoAttack').onclick=()=>{duel.auto=!duel.auto;$('autoAttack').textContent='Auto: '+(duel.auto?'on':'off')};
const fsControls=document.createElement('div');fsControls.id='fsMoves';fsControls.className='fs-controls';for(let i=0;i<4;i++){const b=document.createElement('button');b.className='fs-skill';b.textContent=['Move 1','Ultimate','Quick','Guard'][i];b.onclick=()=>skill(i);fsControls.append(b)}document.querySelector('.arena').append(fsControls);
$('fullScreen').onclick=async()=>{try{const stage=document.querySelector('.arena');if(document.fullscreenElement)await document.exitFullscreen();else if(stage.requestFullscreen)await stage.requestFullscreen();else{stage.classList.toggle('expanded');toast('Fullscreen is unavailable in this browser. Rotate your phone for a wider field.')}}catch(e){toast('Fullscreen is unavailable here. Rotate your phone for a wider field.')}};
function setMode(next){if(active){toast('Pause and return to camp before changing modes.');return}mode=next;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===next));document.querySelector('.instructions').innerHTML=next==='duel'?'<span class="key">DRAG</span> Move &nbsp; <span class="key">1–4</span> Skills &nbsp; <span class="key">SHIFT</span> Dash':'<span class="key">W A S D</span> Move &nbsp; <span class="key">SPACE</span> Attack &nbsp; <span class="key">E</span> Catch';$('feed').textContent=next==='duel'?'STADIUM NOTE · Drag the field to move. Tap one of four skills. Team switching has a 3-second cooldown.':'EXPLORER’S NOTE · Weaken a rival to a gold health bar, get close, then tap CATCH.';$('location').textContent=next==='duel'?'VERDANT STADIUM':next==='explore'?'MOSSFALL MEADOW':next==='arena'?'THORNBOUND ARENA':'SOLSTICE RUINS';$('splash').querySelector('.huge').innerHTML=next==='duel'?'Small Monstars.<br><em>Big arena energy.</em>':next==='explore'?'Meet your<br><em>little legend.</em>':next==='arena'?'How long<br><em>can you last?</em>':'Challenge the<br><em>ancient titan.</em>';$('splash').querySelector('p').textContent=next==='duel'?'Choose four moves, switch your team, and steer with your finger. Take on a new AI rival every round.':'Team up with a Monstar. Battle the wild. Build your collection.';$('start').innerHTML=next==='duel'?'Enter the stadium <span>↗</span>':'Enter the wild <span>↗</span>';$('splash').querySelector('.pill').textContent=next==='duel'?'✦ FREE STADIUM DUELS':'✧ THE WILD IS CALLING';$('splash').classList.remove('hidden');player.max=next==='duel'?stats(save.selected)[0]:maxhp();player.hp=player.max;elapsed=0;enemies=[];bullets=[];renderMoves();team();updateUI()}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
collection=function(){const grid=$('collectionGrid');grid.innerHTML='';species.forEach((s,id)=>{const owned=save.owned.includes(id),i=identity(id),st=stats(id),el=document.createElement('article');el.className='moncard'+(owned?'':' locked');el.innerHTML=`<span class="label">NO. ${String(id+1).padStart(3,'0')} <span style="float:right;color:${s.color}">${s.type}</span></span><canvas width="540" height="405"></canvas><h3>${s.name}</h3><div class="traits"><span>${classes[id]}</span><span>${i.aura} aura</span><span>${i.pattern}</span></div><p>${s.desc}</p><div class="stats-six">${['HP','ATK','DEF','SP. ATK','SP. DEF','SPEED'].map((k,n)=>'<span>'+k+'<b>'+st[n]+'</b></span>').join('')}</div><div class="dna">DNA ${i.dna}<br>${connectedAddress?'Wallet-linked local preview':'Guest local preview'} · ${i.nature} nature</div><button class="${owned?'primary':'smallbtn wide'}" ${owned?'':'disabled'}>${save.selected===id?'✓ Active partner':owned?'Choose partner ↗':id===8?'Defeat the titan':'Catch in the wild'}</button>`;mon(el.querySelector('canvas').getContext('2d'),id,270,225,10.5,0);el.querySelector('button').onclick=()=>{switchPartner(id);collection()};grid.append(el)})};
function signature(){const s=species[save.selected],i=identity(save.selected),el=$('signatureCard');el.innerHTML=`<canvas class="signature-art" width="220" height="160"></canvas><h2>${s.name}</h2><div class="traits"><span>${classes[save.selected]}</span><span>${s.type}</span><span>${i.aura} / ${i.pattern}</span></div><p class="dna">DNA ${i.dna}</p><p class="signature-note">${connectedAddress?'Linked address: '+connectedAddress:'Guest identity — connect Phantom for a separate wallet-linked preview.'}</p><p class="signature-note">Not minted. Local previews have distinct IDs and trait combinations; global uniqueness and ownership are not yet enforced on-chain.</p>`;mon(el.querySelector('canvas').getContext('2d'),save.selected,110,92,4,0)}
tab=function(id){coreTab(id);motion.target=null;motion.vector=null;if(id==='market')signature();if(id==='play'){renderMoves();team()}updateArenaUI()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>tab(b.dataset.go));
function parseSOL(value){if(!/^\d+(\.\d{0,9})?$/.test(value))return null;const [a,b='']=value.split('.');return BigInt(a)*1000000000n+BigInt(b.padEnd(9,'0'))}
function formatSOL(n){const whole=n/1000000000n,frac=(n%1000000000n).toString().padStart(9,'0').replace(/0+$/,'');return whole.toString()+(frac?'.'+frac:'')+' SOL'}
function estimate(){const p=parseSOL($('salePrice').value.trim());if(p===null){['companyCost','royaltyCost','sellerNet'].forEach(id=>$(id).textContent='Enter valid SOL (≤9 decimals)');return}const company=p>0n?1n:0n,royalty=p*100n/10000n;$('companyCost').textContent=formatSOL(company);$('royaltyCost').textContent=formatSOL(royalty);$('sellerNet').textContent=formatSOL(p-company-royalty)}if($('salePrice')){$('salePrice').oninput=estimate;estimate();}
function walletUI(){const connected=!!connectedAddress;$('walletAddress').textContent=connectedAddress||'No wallet connected';$('walletStatus').textContent=connected?'● Phantom connected':'Not connected';$('walletOpen').textContent=connected?connectedAddress.slice(0,4)+'…'+connectedAddress.slice(-4):'Connect Phantom';$('connectPhantom').disabled=connected;$('disconnectPhantom').disabled=!connected;$('refreshBalance').disabled=!connected;updateUI();team();if(!$('collection').classList.contains('hidden'))collection();signature()}
function openWallet(){keys={};motion.target=null;motion.vector=null;if(active&&!paused)$('pause').click();$('phantomBrowse').href='https://phantom.com/ul/browse/'+encodeURIComponent(location.origin+location.pathname)+'?ref='+encodeURIComponent(location.origin);$('walletDialog').showModal();if(connectedAddress){balance();clearInterval(walletTimer);walletTimer=setInterval(()=>{if(!$('walletDialog').open)return;balance()},15000)}}$('walletOpen').onclick=openWallet;$('viewWallet').onclick=openWallet;$('walletClose').onclick=()=>$('walletDialog').close();$('walletDialog').addEventListener('close',()=>{clearInterval(walletTimer);walletTimer=null});
function adoptAddress(key){walletEpoch++;balanceController?.abort();connectedAddress=key?key.toString():null;$('walletBalance').textContent='— SOL';$('balanceTime').textContent='No balance loaded';walletUI();if(connectedAddress){$('walletMessage').textContent='Connected. Loading an on-chain SOL balance…';balance();if($('walletDialog').open){clearInterval(walletTimer);walletTimer=setInterval(()=>{if($('walletDialog').open)balance()},15000)}}else{$('walletMessage').textContent='Disconnected. You can keep playing as a guest.';clearInterval(walletTimer)}}
async function connectPhantom(){walletProvider=window.phantom?.solana;if(!walletProvider?.isPhantom){$('walletMessage').textContent='Phantom is not available in this browser. On iPhone tap Open in Phantom, sign in to this private site there, then connect. On desktop install the official Phantom extension.';return}$('connectPhantom').disabled=true;try{const r=await walletProvider.connect();if(!walletProvider._pmBound){walletProvider.on('accountChanged',adoptAddress);walletProvider.on('disconnect',()=>adoptAddress(null));walletProvider._pmBound=true}adoptAddress(r.publicKey)}catch(e){$('walletMessage').textContent=e.code===4001?'Connection declined. No wallet connection was made.':'Unable to connect Phantom. Open this page directly in Phantom or its supported browser extension.';$('connectPhantom').disabled=false}}
async function balance(){if(!connectedAddress)return;balanceController?.abort();balanceController=new AbortController();const controller=balanceController,epoch=walletEpoch,address=connectedAddress,network=$('walletNetwork').value;let timed=false;const timer=setTimeout(()=>{timed=true;controller.abort()},10000);$('walletBalance').textContent='Loading…';try{const r=await fetch(network==='devnet'?'https://api.devnet.solana.com':'https://api.mainnet-beta.solana.com',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'getBalance',params:[address,{commitment:'confirmed'}]}),signal:controller.signal});if(!r.ok)throw new Error('RPC HTTP '+r.status);const data=await r.json();if(data.error)throw new Error(data.error.message);if(!Number.isSafeInteger(data.result?.value)||data.result.value<0)throw new Error('Invalid RPC balance');if(epoch!==walletEpoch||address!==connectedAddress||network!==$('walletNetwork').value)return;$('walletBalance').textContent=formatSOL(BigInt(data.result.value));$('balanceTime').textContent='Confirmed · '+new Date().toLocaleTimeString()+' · '+network;$('walletMessage').textContent='Read-only balance. Battle points and camp shards do not change your SOL.'}catch(e){if(epoch!==walletEpoch||controller!==balanceController)return;if(e.name==='AbortError'&&!timed)return;$('walletBalance').textContent='Unavailable';$('balanceTime').textContent='No confirmed balance available';$('walletMessage').textContent='Solana RPC could not be reached or is rate limited. Your balance is not shown as zero. Try Refresh later.'}finally{clearTimeout(timer)}}
$('connectPhantom').onclick=connectPhantom;$('disconnectPhantom').onclick=async()=>{try{await walletProvider?.disconnect();adoptAddress(null)}catch(e){$('walletMessage').textContent='Phantom could not disconnect. Try again in the wallet.'}};$('refreshBalance').onclick=balance;$('walletNetwork').onchange=()=>{walletEpoch++;balanceController?.abort();$('walletBalance').textContent='— SOL';$('balanceTime').textContent='No balance loaded';if(connectedAddress)balance()};
const pauseAction=$('pause').onclick;$('pause').onclick=()=>{pauseAction();motion.target=null;motion.vector=null;updateArenaUI()};
setMode('duel');signature();
